CREATE TABLE iam_accounts (id VARCHAR(36) PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, display_name VARCHAR(128) NOT NULL, status VARCHAR(16) NOT NULL, must_change_password BOOLEAN NOT NULL, security_revision BIGINT UNSIGNED NOT NULL, failed_attempts INT NOT NULL, locked_until DATETIME(6) NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
CREATE TABLE iam_local_credentials (account_id VARCHAR(36) PRIMARY KEY, password_hash TEXT NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_iam_credential_account FOREIGN KEY(account_id) REFERENCES iam_accounts(id) ON DELETE CASCADE);
CREATE TABLE iam_roles (id VARCHAR(36) PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, description TEXT NOT NULL, active BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, system BOOLEAN NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
CREATE TABLE iam_account_roles (account_id VARCHAR(36) NOT NULL, role_id VARCHAR(36) NOT NULL, active BOOLEAN NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(account_id,role_id), CONSTRAINT fk_iam_ar_account FOREIGN KEY(account_id) REFERENCES iam_accounts(id) ON DELETE CASCADE, CONSTRAINT fk_iam_ar_role FOREIGN KEY(role_id) REFERENCES iam_roles(id) ON DELETE CASCADE);
CREATE TABLE iam_role_permissions (role_id VARCHAR(36) NOT NULL, permission_key VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(role_id,permission_key), CONSTRAINT fk_iam_rp_role FOREIGN KEY(role_id) REFERENCES iam_roles(id) ON DELETE CASCADE);
CREATE TABLE iam_sessions (id_hash VARBINARY(32) PRIMARY KEY, account_id VARCHAR(36) NOT NULL, csrf_hash VARBINARY(32) NOT NULL, security_revision BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL, last_seen_at DATETIME(6) NOT NULL, idle_expires_at DATETIME(6) NOT NULL, absolute_expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6) NULL, INDEX ix_iam_sessions_account(account_id), CONSTRAINT fk_iam_session_account FOREIGN KEY(account_id) REFERENCES iam_accounts(id) ON DELETE CASCADE);
